    fachgeschaefte_ids: ['id1', 'id2', 'id3'],
    fachgeschaefte_namen: ['Laden A', 'Laden B', 'Laden C'],
    distanzen_km: [15.5, 23.8, 45.2],
    anzahl: 3,
    naechstes_geschaeft: 'Laden A',
    naechste_distanz_km: 15.5
  }
}];

// Genau der Code aus dem Update-Node
const payload = JSON.stringify({
  properties: {
    'zukünftiger Arbeitgeber': {
      relation: $json.fachgeschaefte_ids.map(id => ({ id }))
    },
    'Kommentar': {
      rich_text: [
        {
          type: 'text',
          text: {
            content: 'Zugeordnete Geschäfte (10-100 km):\n' + $json.fachgeschaefte_namen.map((name, i) => `${i+1}. ${name}: ${$json.distanzen_km[i]} km`).join('\n')
          }
        }
      ]
    }
  }
});

return [{ json: { payload: JSON.parse(payload) } }];
